const HTML = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>HexSum \u2014 Free Online Hash Generator & Checksum Verifier (MD5, SHA-1, SHA-256, SHA-384, SHA-512)</title>\n<meta name=\"description\" content=\"HexSum is a free online hash generator and checksum verifier. Compute MD5, SHA-1, SHA-256, SHA-384 and SHA-512 for text or files instantly in your browser, verify checksums, and identify unknown hash algorithms. No signup, unlimited free usage.\">\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<script id=\"hexsum-lib\">\n/* ============================================================================\n * HexSum core library \u2014 pure, dependency-free hash utilities.\n * MD5 (RFC 1321) and SHA-1 (FIPS 180-4) implemented in plain JavaScript because\n * Web Crypto does not provide them. SHA-256/384/512 are handled via Web Crypto\n * by the page; this lib exposes only sync, testable logic.\n * Exposed as: globalThis.HexSumLib\n * ========================================================================== */\n(function () {\n  'use strict';\n\n  /* ---------------- byte / hex helpers ---------------- */\n\n  function bytesToHex(bytes) {\n    var s = '';\n    for (var i = 0; i < bytes.length; i++) {\n      s += (bytes[i] < 16 ? '0' : '') + bytes[i].toString(16);\n    }\n    return s;\n  }\n\n  function stringToBytes(str) {\n    if (typeof TextEncoder !== 'undefined') return new TextEncoder().encode(str);\n    // Fallback (very old runtimes): manual UTF-8 encode\n    var out = [];\n    for (var i = 0; i < str.length; i++) {\n      var c = str.charCodeAt(i);\n      if (c < 128) out.push(c);\n      else if (c < 2048) { out.push(192 | (c >> 6), 128 | (c & 63)); }\n      else if (c >= 55296 && c <= 56319 && i + 1 < str.length) {\n        var d = str.charCodeAt(++i);\n        c = 65536 + ((c - 55296) << 10) + (d - 57344);\n        out.push(240 | (c >> 18), 128 | ((c >> 12) & 63), 128 | ((c >> 6) & 63), 128 | (c & 63));\n      } else out.push(224 | (c >> 12), 128 | ((c >> 6) & 63), 128 | (c & 63));\n    }\n    return new Uint8Array(out);\n  }\n\n  /* ---------------- MD5 (RFC 1321, incremental) ---------------- */\n\n  var MD5_S = [7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22, 7, 12, 17, 22,\n               5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20, 5, 9, 14, 20,\n               4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23, 4, 11, 16, 23,\n               6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21, 6, 10, 15, 21];\n  var MD5_K = (function () {\n    var k = new Array(64);\n    for (var i = 0; i < 64; i++) k[i] = Math.floor(Math.abs(Math.sin(i + 1)) * 4294967296) >>> 0;\n    return k;\n  })();\n\n  function MD5Hasher() {\n    this._a = 0x67452301; this._b = 0xefcdab89;\n    this._c = 0x98badcfe; this._d = 0x10325476;\n    this._len = 0;\n    this._buf = new Uint8Array(64);\n    this._bufLen = 0;\n  }\n\n  MD5Hasher.prototype._transform = function (block) {\n    var x = new Uint32Array(16);\n    var dv = new DataView(block.buffer, block.byteOffset, 64);\n    for (var i = 0; i < 16; i++) x[i] = dv.getUint32(i * 4, true);\n    var a = this._a, b = this._b, c = this._c, d = this._d;\n    for (var j = 0; j < 64; j++) {\n      var f, g;\n      if (j < 16)      { f = (b & c) | (~b & d); g = j; }\n      else if (j < 32) { f = (d & b) | (~d & c); g = (5 * j + 1) % 16; }\n      else if (j < 48) { f = b ^ c ^ d;          g = (3 * j + 5) % 16; }\n      else             { f = c ^ (b | ~d);       g = (7 * j) % 16; }\n      f = (f + a + MD5_K[j] + x[g]) >>> 0;\n      a = d; d = c; c = b;\n      var s = MD5_S[j];\n      b = (b + ((f << s) | (f >>> (32 - s)))) >>> 0;\n    }\n    this._a = (this._a + a) >>> 0;\n    this._b = (this._b + b) >>> 0;\n    this._c = (this._c + c) >>> 0;\n    this._d = (this._d + d) >>> 0;\n  };\n\n  MD5Hasher.prototype.update = function (bytes) {\n    var off = 0, remaining = bytes.length;\n    this._len += remaining;\n    if (this._bufLen > 0) {\n      var take = Math.min(64 - this._bufLen, remaining);\n      this._buf.set(bytes.subarray(0, take), this._bufLen);\n      this._bufLen += take; off += take; remaining -= take;\n      if (this._bufLen === 64) { this._transform(this._buf); this._bufLen = 0; }\n    }\n    while (remaining >= 64) {\n      this._transform(bytes.subarray(off, off + 64));\n      off += 64; remaining -= 64;\n    }\n    if (remaining > 0) {\n      this._buf.set(bytes.subarray(off, off + remaining), 0);\n      this._bufLen = remaining;\n    }\n    return this;\n  };\n\n  MD5Hasher.prototype.digest = function () {\n    var bitLen = this._len * 8;\n    var padLen = this._bufLen < 56 ? 56 - this._bufLen : 120 - this._bufLen;\n    var pad = new Uint8Array(padLen);\n    pad[0] = 0x80;\n    this.update(pad);\n    var lenBytes = new Uint8Array(8);\n    var dv = new DataView(lenBytes.buffer);\n    dv.setUint32(0, bitLen >>> 0, true);\n    dv.setUint32(4, Math.floor(bitLen / 4294967296) >>> 0, true);\n    this.update(lenBytes);\n    var words = [this._a, this._b, this._c, this._d];\n    var s = '';\n    for (var i = 0; i < 4; i++)\n      for (var j = 0; j < 4; j++) {\n        var byte = (words[i] >>> (j * 8)) & 255;\n        s += (byte < 16 ? '0' : '') + byte.toString(16);\n      }\n    return s;\n  };\n\n  function md5Hex(bytes) { return new MD5Hasher().update(bytes).digest(); }\n\n  /* ---------------- SHA-1 (FIPS 180-4, incremental) ---------------- */\n\n  function SHA1Hasher() {\n    this._h = [0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476, 0xc3d2e1f0];\n    this._len = 0;\n    this._buf = new Uint8Array(64);\n    this._bufLen = 0;\n  }\n\n  function rol(v, n) { return ((v << n) | (v >>> (32 - n))) >>> 0; }\n\n  SHA1Hasher.prototype._transform = function (block) {\n    var w = new Uint32Array(80);\n    var dv = new DataView(block.buffer, block.byteOffset, 64);\n    var i;\n    for (i = 0; i < 16; i++) w[i] = dv.getUint32(i * 4, false);\n    for (i = 16; i < 80; i++) w[i] = rol(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);\n    var a = this._h[0], b = this._h[1], c = this._h[2], d = this._h[3], e = this._h[4];\n    for (i = 0; i < 80; i++) {\n      var f, k;\n      if (i < 20)      { f = (b & c) | (~b & d); k = 0x5a827999; }\n      else if (i < 40) { f = b ^ c ^ d;          k = 0x6ed9eba1; }\n      else if (i < 60) { f = (b & c) | (b & d) | (c & d); k = 0x8f1bbcdc; }\n      else             { f = b ^ c ^ d;          k = 0xca62c1d6; }\n      var t = (rol(a, 5) + f + e + k + w[i]) >>> 0;\n      e = d; d = c; c = rol(b, 30); b = a; a = t;\n    }\n    this._h[0] = (this._h[0] + a) >>> 0;\n    this._h[1] = (this._h[1] + b) >>> 0;\n    this._h[2] = (this._h[2] + c) >>> 0;\n    this._h[3] = (this._h[3] + d) >>> 0;\n    this._h[4] = (this._h[4] + e) >>> 0;\n  };\n\n  SHA1Hasher.prototype.update = MD5Hasher.prototype.update; // identical buffering logic\n\n  SHA1Hasher.prototype.digest = function () {\n    var bitLen = this._len * 8;\n    var padLen = this._bufLen < 56 ? 56 - this._bufLen : 120 - this._bufLen;\n    var pad = new Uint8Array(padLen);\n    pad[0] = 0x80;\n    this.update(pad);\n    var lenBytes = new Uint8Array(8);\n    var dv = new DataView(lenBytes.buffer);\n    dv.setUint32(0, Math.floor(bitLen / 4294967296) >>> 0, false);\n    dv.setUint32(4, bitLen >>> 0, false);\n    this.update(lenBytes);\n    var s = '';\n    for (var i = 0; i < 5; i++)\n      for (var j = 3; j >= 0; j--) {\n        var byte = (this._h[i] >>> (j * 8)) & 255;\n        s += (byte < 16 ? '0' : '') + byte.toString(16);\n      }\n    return s;\n  };\n\n  function sha1Hex(bytes) { return new SHA1Hasher().update(bytes).digest(); }\n\n  /* ---------------- hash identification & verdict ---------------- */\n\n  var ALGO_TABLE = {\n    32:  { algorithm: 'MD5',     bits: 128, note: 'Broken \u2014 use for non-security checksums only.' },\n    40:  { algorithm: 'SHA-1',   bits: 160, note: 'Legacy \u2014 collisions demonstrated (SHAttered, 2017).' },\n    64:  { algorithm: 'SHA-256', bits: 256, note: 'Secure \u2014 the modern default.' },\n    96:  { algorithm: 'SHA-384', bits: 384, note: 'Secure \u2014 SHA-2 family, compliance contexts.' },\n    128: { algorithm: 'SHA-512', bits: 512, note: 'Secure \u2014 largest output, maximum margin.' }\n  };\n\n  function normalizeHash(raw) {\n    if (raw == null) return '';\n    return String(raw).replace(/[\\s:\\-]/g, '').toLowerCase();\n  }\n\n  function isHexString(s) {\n    return s.length > 0 && /^[0-9a-f]+$/.test(s);\n  }\n\n  // Returns { algorithm, bits, hexLength, note } or null when unrecognised.\n  function detectAlgorithm(raw) {\n    var h = normalizeHash(raw);\n    if (!isHexString(h)) return null;\n    var entry = ALGO_TABLE[h.length];\n    if (!entry) return null;\n    return {\n      algorithm: entry.algorithm,\n      bits: entry.bits,\n      hexLength: h.length,\n      note: entry.note,\n      hash: h\n    };\n  }\n\n  // Compare two hash strings. Returns { match, valid, algorithm, expected, detail }.\n  function compareHashes(a, b) {\n    var na = normalizeHash(a);\n    var nb = normalizeHash(b);\n    if (!na || !nb) {\n      return { match: false, valid: false, algorithm: null,\n               detail: 'Both a computed hash and an expected hash are needed to verify.' };\n    }\n    if (!isHexString(nb)) {\n      return { match: false, valid: false, algorithm: null,\n               detail: 'Expected value is not valid hexadecimal.' };\n    }\n    var detected = detectAlgorithm(nb);\n    var match = na === nb;\n    return {\n      match: match,\n      valid: true,\n      algorithm: detected ? detected.algorithm : null,\n      expectedLength: nb.length,\n      detail: match\n        ? 'Hashes are identical \u2014 integrity confirmed.'\n        : 'Hashes differ \u2014 data was altered or corrupted.'\n    };\n  }\n\n  /* ---------------- exports ---------------- */\n\n  globalThis.HexSumLib = {\n    bytesToHex: bytesToHex,\n    stringToBytes: stringToBytes,\n    md5Hex: md5Hex,\n    sha1Hex: sha1Hex,\n    MD5Hasher: MD5Hasher,\n    SHA1Hasher: SHA1Hasher,\n    normalizeHash: normalizeHash,\n    isHexString: isHexString,\n    detectAlgorithm: detectAlgorithm,\n    compareHashes: compareHashes,\n    ALGO_TABLE: ALGO_TABLE\n  };\n})();\n\n</script>\n<script type=\"application/ld+json\">\n{\n  \"@context\": \"https://schema.org\",\n  \"@type\": \"FAQPage\",\n  \"mainEntity\": [\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Is HexSum free, and do I need to sign up?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Yes. HexSum is completely free with unlimited usage. There is no signup, no account, no paywall and no watermark. Everything runs in your browser, so there is nothing to pay for and nothing to register.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Are my files or text uploaded to a server when I hash them?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"No. HexSum computes every hash locally in your browser using the Web Crypto API and built-in JavaScript. Your text and files never leave your device. You can even disconnect from the internet after the page loads and hashing will keep working.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How do I verify a downloaded file's checksum with HexSum?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"Drop the downloaded file into HexSum, wait for the five hashes to appear, then paste the checksum published by the software vendor into the verdict box. HexSum auto-detects the algorithm from the hash length and shows a MATCH or MISMATCH verdict. A match means the file arrived intact; a mismatch means it is corrupt or has been tampered with.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Which hash algorithm should I use: MD5, SHA-1, SHA-256, SHA-384 or SHA-512?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"For anything security-related, use SHA-256 or SHA-512. MD5 and SHA-1 are broken for security purposes and should only be used for non-security checksums such as detecting accidental corruption or identifying duplicate files. SHA-256 is the modern default; SHA-512 offers the largest security margin and is often faster on 64-bit hardware.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"Can I use a plain SHA-256 hash to store passwords?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"No. Plain SHA-256 is far too fast to be a safe password hash and offers no salt, so identical passwords produce identical hashes that are trivially crackable with GPUs and rainbow tables. Use a dedicated password-hashing function such as bcrypt, scrypt or Argon2id, which are intentionally slow and include automatic salting.\" }\n    },\n    {\n      \"@type\": \"Question\",\n      \"name\": \"How does HexSum identify an unknown hash algorithm?\",\n      \"acceptedAnswer\": { \"@type\": \"Answer\", \"text\": \"HexSum looks at the length of the hexadecimal string. A 32-character hash is MD5, 40 is SHA-1, 64 is SHA-256, 96 is SHA-384 and 128 is SHA-512. Paste any hash into the Identify tab and HexSum reports the most likely algorithm, its bit length and a security note.\" }\n    }\n  ]\n}\n</script>\n<style>\n  .hash-mono { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; word-break: break-all; }\n  .tab-active { background-color: #FBBF24; color: #451A03; }\n  .tab-idle { background-color: transparent; color: #D6D3D1; }\n  .tab-idle:hover { color: #FBBF24; }\n  .copy-flash { background-color: #FEF3C7 !important; }\n  details.faq-item summary::-webkit-details-marker { display: none; }\n</style>\n</head>\n<body id=\"top\" class=\"bg-stone-100 text-stone-900 antialiased\">\n\n<!-- ============ STICKY HEADER ============ -->\n<header class=\"sticky top-0 z-50 bg-[#451A03] shadow-lg\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 h-16 flex items-center justify-between\">\n    <a href=\"#top\" class=\"flex items-center gap-2\">\n      <span class=\"inline-flex h-9 w-9 items-center justify-center rounded-lg bg-amber-400 text-[#451A03] font-black text-lg\">#</span>\n      <span class=\"text-2xl font-extrabold tracking-tight text-amber-400\">HexSum</span>\n    </a>\n    <nav class=\"flex items-center gap-5 text-sm font-medium\">\n      <a href=\"#top\" class=\"text-stone-200 hover:text-amber-400 transition\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"text-stone-200 hover:text-amber-400 transition\">More Tools</a>\n    </nav>\n  </div>\n</header>\n\n<!-- ============ HERO ============ -->\n<section class=\"bg-gradient-to-br from-[#451A03] via-[#78350A] to-[#451A03] text-stone-100\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 py-10 sm:py-14 text-center\">\n    <span class=\"inline-block rounded-full border border-amber-400/60 bg-amber-400/10 px-4 py-1.5 text-xs font-bold uppercase tracking-[0.18em] text-amber-300\">Unlimited Free Usage &middot; No Signup</span>\n    <h1 class=\"mt-4 text-3xl sm:text-5xl font-extrabold tracking-tight text-white\">Hash Generator &amp; Checksum Verifier</h1>\n    <p class=\"mt-3 max-w-2xl mx-auto text-stone-300 text-sm sm:text-base\">Compute <span class=\"text-amber-300 font-semibold\">MD5, SHA-1, SHA-256, SHA-384 &amp; SHA-512</span> for text or files \u2014 all five at once, entirely in your browser. Verify checksums and identify unknown hashes in seconds.</p>\n    <div class=\"mt-5 flex flex-wrap justify-center gap-2 text-[11px] font-semibold\">\n      <span class=\"rounded-full bg-black/30 px-3 py-1 text-amber-200 border border-amber-400/30\">100% in-browser</span>\n      <span class=\"rounded-full bg-black/30 px-3 py-1 text-amber-200 border border-amber-400/30\">Nothing uploaded</span>\n      <span class=\"rounded-full bg-black/30 px-3 py-1 text-amber-200 border border-amber-400/30\">Chunked file hashing</span>\n      <span class=\"rounded-full bg-black/30 px-3 py-1 text-amber-200 border border-amber-400/30\">Hash identifier</span>\n    </div>\n  </div>\n</section>\n\n<!-- TOP AD (verbatim) -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pt-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <div class=\"origin-top scale-[0.44] sm:scale-100 shrink-0\">\n        <script>\n          atOptions = { 'key' : '4e68ac77881c17fe128a46565d9a4e8c', 'format' : 'iframe', 'height' : 90, 'width' : 728, 'params' : {} };\n        </script>\n        <script src=\"https://www.highrevenueformat.com/4e68ac77881c17fe128a46565d9a4e8c/invoke.js\"></script>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!-- ============ TOOL ============ -->\n<main class=\"mx-auto max-w-6xl px-4 sm:px-6 py-6\">\n\n  <!-- INPUT LAB PANE -->\n  <section class=\"rounded-2xl bg-stone-900 shadow-xl ring-1 ring-amber-900/40 overflow-hidden\">\n    <div class=\"flex items-center justify-between px-5 sm:px-7 pt-5\">\n      <h2 class=\"text-lg sm:text-xl font-bold text-amber-300\">Hash Lab &mdash; Input</h2>\n      <div class=\"flex rounded-lg bg-black/40 p-1 text-xs sm:text-sm font-semibold\" role=\"tablist\" aria-label=\"Input mode\">\n        <button id=\"tab-text\" role=\"tab\" class=\"tab-active rounded-md px-3 sm:px-4 py-2 transition\" onclick=\"setMode('text')\">Text</button>\n        <button id=\"tab-file\" role=\"tab\" class=\"tab-idle rounded-md px-3 sm:px-4 py-2 transition\" onclick=\"setMode('file')\">File</button>\n        <button id=\"tab-identify\" role=\"tab\" class=\"tab-idle rounded-md px-3 sm:px-4 py-2 transition\" onclick=\"setMode('identify')\">Identify Hash</button>\n      </div>\n    </div>\n\n    <!-- TEXT MODE -->\n    <div id=\"pane-text\" class=\"px-5 sm:px-7 py-5\">\n      <label for=\"text-input\" class=\"block text-xs font-semibold uppercase tracking-wider text-stone-400 mb-2\">Paste or type text to hash</label>\n      <textarea id=\"text-input\" rows=\"5\" placeholder=\"Type or paste any text here \u2014 all five hashes compute live as you type\u2026\"\n        class=\"w-full rounded-xl bg-black/40 border border-stone-700 text-stone-100 placeholder-stone-500 p-4 text-sm hash-mono focus:outline-none focus:ring-2 focus:ring-amber-400 focus:border-amber-400\"></textarea>\n      <div class=\"mt-2 flex flex-wrap items-center justify-between gap-2 text-xs text-stone-400\">\n        <span><span id=\"char-count\">0</span> characters &middot; <span id=\"byte-count\">0</span> UTF-8 bytes</span>\n        <span class=\"flex items-center gap-2\">\n          <button onclick=\"clearText()\" class=\"rounded-md bg-stone-700 hover:bg-stone-600 text-stone-200 px-3 py-1.5 font-semibold transition\">Clear</button>\n          <button onclick=\"hashTextNow()\" class=\"rounded-md bg-amber-400 hover:bg-amber-300 text-[#451A03] px-4 py-1.5 font-bold transition\">Compute Hashes</button>\n        </span>\n      </div>\n    </div>\n\n    <!-- FILE MODE -->\n    <div id=\"pane-file\" class=\"px-5 sm:px-7 py-5 hidden\">\n      <div id=\"drop-zone\" class=\"rounded-xl border-2 border-dashed border-stone-600 bg-black/30 px-6 py-10 text-center cursor-pointer transition hover:border-amber-400 hover:bg-black/50\">\n        <div class=\"text-4xl mb-2\">\ud83d\udcc4</div>\n        <p class=\"text-stone-200 font-semibold text-sm sm:text-base\">Drop a file here, or <span class=\"text-amber-300 underline\">click to browse</span></p>\n        <p class=\"mt-1 text-xs text-stone-500\">Hashed in 4&nbsp;MB chunks &middot; files never leave your device</p>\n        <input id=\"file-input\" type=\"file\" class=\"hidden\">\n      </div>\n      <div id=\"file-meta\" class=\"hidden mt-3 text-xs text-stone-400\"></div>\n      <div class=\"mt-3 hidden\" id=\"progress-wrap\">\n        <div class=\"h-2.5 rounded-full bg-black/50 overflow-hidden\">\n          <div id=\"progress-bar\" class=\"h-full w-0 bg-amber-400 rounded-full transition-all\"></div>\n        </div>\n        <p id=\"progress-label\" class=\"mt-1 text-xs text-stone-400\">Reading file\u2026</p>\n      </div>\n    </div>\n\n    <!-- IDENTIFY MODE -->\n    <div id=\"pane-identify\" class=\"px-5 sm:px-7 py-5 hidden\">\n      <label for=\"identify-input\" class=\"block text-xs font-semibold uppercase tracking-wider text-stone-400 mb-2\">Paste an unknown hash \u2014 HexSum guesses the algorithm</label>\n      <input id=\"identify-input\" type=\"text\" spellcheck=\"false\" autocomplete=\"off\" placeholder=\"e.g. 5d41402abc4b2a76b9719d911017c592\"\n        class=\"w-full rounded-xl bg-black/40 border border-stone-700 text-stone-100 placeholder-stone-500 p-4 text-sm hash-mono focus:outline-none focus:ring-2 focus:ring-amber-400 focus:border-amber-400\">\n      <div id=\"identify-result\" class=\"mt-3\"></div>\n      <p class=\"mt-2 text-xs text-stone-500\">Detection is based on hexadecimal length: 32&thinsp;=&thinsp;MD5, 40&thinsp;=&thinsp;SHA-1, 64&thinsp;=&thinsp;SHA-256, 96&thinsp;=&thinsp;SHA-384, 128&thinsp;=&thinsp;SHA-512.</p>\n    </div>\n  </section>\n\n  <!-- OUTPUT CARDS -->\n  <section class=\"mt-6\">\n    <div class=\"flex flex-wrap items-center justify-between gap-3 mb-3\">\n      <h2 class=\"text-lg sm:text-xl font-bold text-[#451A03]\">Digests <span class=\"text-sm font-medium text-stone-500\">&mdash; all five, computed at once</span></h2>\n      <div class=\"flex items-center gap-2 text-xs\">\n        <button onclick=\"toggleCase()\" id=\"case-btn\" class=\"rounded-md border border-stone-300 bg-white px-3 py-1.5 font-semibold text-stone-700 hover:border-amber-500 transition\">UPPERCASE</button>\n        <button onclick=\"copyAll()\" class=\"rounded-md bg-[#451A03] hover:bg-[#5b2304] text-amber-300 px-3 py-1.5 font-semibold transition\">Copy all as JSON</button>\n      </div>\n    </div>\n    <div id=\"algo-cards\" class=\"grid gap-3 sm:grid-cols-2 lg:grid-cols-1\"></div>\n    <p id=\"no-input-hint\" class=\"mt-2 text-sm text-stone-500 italic\">Enter text or choose a file above to generate hashes.</p>\n  </section>\n\n  <!-- VERDICT BOX -->\n  <section class=\"mt-6 rounded-2xl bg-white shadow ring-1 ring-stone-200 overflow-hidden\">\n    <div class=\"px-5 sm:px-7 py-5\">\n      <h2 class=\"text-lg sm:text-xl font-bold text-[#451A03]\">Checksum Verdict <span class=\"text-sm font-medium text-stone-500\">&mdash; paste the expected hash</span></h2>\n      <p class=\"mt-1 text-xs text-stone-500\">HexSum auto-detects the algorithm from the hash length and compares it against the matching computed digest.</p>\n      <div class=\"mt-3 flex flex-col sm:flex-row gap-2\">\n        <input id=\"expected-input\" type=\"text\" spellcheck=\"false\" autocomplete=\"off\" placeholder=\"Paste the expected / published checksum here\u2026\"\n          class=\"flex-1 rounded-xl border border-stone-300 p-3 text-sm hash-mono focus:outline-none focus:ring-2 focus:ring-amber-400 focus:border-amber-400\">\n        <button onclick=\"verifyNow()\" class=\"rounded-xl bg-amber-400 hover:bg-amber-300 text-[#451A03] font-bold px-6 py-3 text-sm transition\">Verify</button>\n      </div>\n      <div id=\"verdict-box\" class=\"mt-3 hidden rounded-xl p-4 text-sm\"></div>\n    </div>\n  </section>\n\n  <!-- SECURITY GUIDANCE -->\n  <section class=\"mt-6 rounded-2xl bg-amber-50 ring-1 ring-amber-200 overflow-hidden\">\n    <div class=\"px-5 sm:px-7 py-5\">\n      <h2 class=\"text-lg sm:text-xl font-bold text-[#451A03]\">Honest Security Guidance</h2>\n      <div class=\"mt-3 grid gap-3 sm:grid-cols-3 text-sm\">\n        <div class=\"rounded-xl bg-white p-4 ring-1 ring-red-200\">\n          <p class=\"font-bold text-red-700\">MD5 &amp; SHA-1 are legacy</p>\n          <p class=\"mt-1 text-stone-600 text-[13px]\">Both are cryptographically <strong>broken</strong> \u2014 attackers can craft two different inputs with the same hash (collisions). Use them only for non-security checksums: spotting accidental corruption, deduplicating files, cache keys. Never for signatures, certificates or integrity you must trust.</p>\n        </div>\n        <div class=\"rounded-xl bg-white p-4 ring-1 ring-amber-200\">\n          <p class=\"font-bold text-amber-700\">SHA-256 / 384 / 512 are secure</p>\n          <p class=\"mt-1 text-stone-600 text-[13px]\">No practical attacks exist against the SHA-2 family. <strong>SHA-256 is the modern default</strong> for file verification and data integrity; SHA-512 gives the biggest security margin and is often faster on 64-bit hardware.</p>\n        </div>\n        <div class=\"rounded-xl bg-white p-4 ring-1 ring-stone-300\">\n          <p class=\"font-bold text-stone-800\">Plain hashes are NOT password storage</p>\n          <p class=\"mt-1 text-stone-600 text-[13px]\">A raw SHA-256 of a password is dangerously weak: it's unsalted and billions of guesses per second are possible on a GPU. For passwords use <strong>bcrypt, scrypt or Argon2id</strong> \u2014 deliberately slow, automatically salted password-hashing functions.</p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n</main>\n\n<!-- BOTTOM AD (verbatim) -->\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pb-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <script async src=\"https://js.wpadmngr.com/static/adManager.js\" data-admpid=\"464498\"></script>\n    </div>\n  </div>\n</div>\n\n<!-- ============ SEO ARTICLE ============ -->\n<!--ARTICLE-START-->\n<article class=\"mx-auto max-w-6xl px-4 sm:px-6 pb-10\">\n  <div class=\"rounded-2xl bg-white ring-1 ring-stone-200 px-5 sm:px-10 py-8 prose-stone max-w-none\">\n    <h2 class=\"text-2xl sm:text-3xl font-extrabold text-[#451A03]\">Hash Generators, Checksums &amp; File Verification: The Complete Guide</h2>\n\n    <p class=\"mt-4 text-stone-700 leading-relaxed\">Every file you download, every software update you install, and every message you send relies on a quiet mathematical workhorse: the <strong>hash function</strong>. A hash function takes input of any size \u2014 a three-letter word or a four-gigabyte disk image \u2014 and squeezes it down into a short, fixed-length fingerprint called a <strong>hash</strong>, <strong>digest</strong> or <strong>checksum</strong>. The same input always produces exactly the same fingerprint, while changing even a single character produces a wildly different one. That simple property makes hashes one of the most useful tools in computing, powering everything from download verification to blockchain networks.</p>\n\n    <p class=\"mt-4 text-stone-700 leading-relaxed\">This guide explains what hash generators do, how the five most common algorithms differ, how to verify a file's checksum step by step, how to identify an unknown hash from its length alone, and \u2014 just as importantly \u2014 where hashes should <em>not</em> be trusted. By the end, you will know exactly which algorithm to reach for and which mistakes to avoid.</p>\n\n    <h3 class=\"mt-8 text-xl font-bold text-[#451A03]\">What exactly is a hash function?</h3>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\">A cryptographic hash function is a one-way mathematical transformation with four essential properties. First, it is <strong>deterministic</strong>: hashing the same data twice gives the same result every time. Second, it is <strong>fixed-size</strong>: no matter how large the input, the output is always the same length \u2014 32 hexadecimal characters for MD5, 64 for SHA-256, 128 for SHA-512. Third, it exhibits the <strong>avalanche effect</strong>: flipping one bit of input changes roughly half the output bits, so similar inputs produce completely unrelated hashes. Fourth, it is <strong>one-way</strong>: given only a hash, there is no practical way to reconstruct the original input.</p>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\">Two further properties matter for security. <strong>Collision resistance</strong> means it should be infeasible to find two different inputs that produce the same hash. <strong>Preimage resistance</strong> means that given a target hash, it should be infeasible to find any input that produces it. When an algorithm loses collision resistance \u2014 as MD5 did in 2004 and SHA-1 did with Google's SHAttered attack in 2017 \u2014 it can no longer be trusted wherever an attacker might benefit from forging a matching fingerprint.</p>\n\n    <h3 class=\"mt-8 text-xl font-bold text-[#451A03]\">The five algorithms, explained</h3>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\"><strong>MD5</strong> produces a 128-bit digest shown as 32 hexadecimal characters. Designed in 1992, it is extremely fast and still ubiquitous in legacy systems, but it is cryptographically broken: researchers can deliberately generate two different files with the identical MD5 hash. It remains perfectly fine for non-adversarial jobs such as detecting accidental corruption, identifying duplicate files, or generating cache keys \u2014 anywhere speed matters and nobody is trying to cheat.</p>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\"><strong>SHA-1</strong> produces a 160-bit digest (40 hex characters). It was the dominant standard for more than a decade \u2014 Git still uses it for commit identifiers \u2014 but practical collision attacks have been demonstrated, so it is deprecated for security use. You will still encounter SHA-1 checksums published alongside older software releases; treat them as weak evidence, not proof.</p>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\"><strong>SHA-256</strong> produces a 256-bit digest (64 hex characters) and is the current gold standard for general use. It secures Bitcoin, TLS certificates, software distribution channels and countless APIs. No practical attack against SHA-256 is known, and cryptographers consider it safe for the foreseeable future. When in doubt, <strong>SHA-256 is the algorithm you should choose</strong>.</p>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\"><strong>SHA-384</strong> produces a 384-bit digest (96 hex characters). It belongs to the same SHA-2 family as SHA-256 but truncates the output of the SHA-512 computation, giving a larger security margin. You will mostly meet it in enterprise certificate infrastructure and government compliance contexts that mandate longer digests.</p>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\"><strong>SHA-512</strong> produces a 512-bit digest (128 hex characters) \u2014 the largest output of the five, and therefore the largest safety margin. Counterintuitively, it is often 20\u201330% <em>faster</em> than SHA-256 on modern 64-bit processors, because its internal operations are natively 64-bit. Choose SHA-512 when you want maximum assurance or when benchmarking shows it is faster on your hardware.</p>\n\n    <h3 class=\"mt-8 text-xl font-bold text-[#451A03]\">Checksums: verifying that a download is intact</h3>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\">The most common everyday use of a hash generator is <strong>checksum verification</strong>. When you download an operating-system ISO, a firmware update, or any large installer, the vendor publishes a checksum \u2014 usually SHA-256 \u2014 next to the download link. After downloading, you compute the hash of your copy and compare the two strings character by character. If they match exactly, the file arrived intact and unmodified. If they differ, the download is corrupt or has been tampered with, and you should delete it and re-download from an official mirror.</p>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\">This matters because downloads can be corrupted by flaky networks, interrupted transfers, or failing storage \u2014 and, more seriously, because attackers occasionally compromise download mirrors to distribute malware disguised as legitimate software. A checksum comparison is a thirty-second habit that defeats both problems at once, provided you fetch the published checksum from the vendor's official site (ideally over HTTPS) rather than from the same mirror as the file.</p>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\">HexSum streamlines this workflow: drop the file into the tool, let it compute all five digests, then paste the vendor's published checksum into the verdict box. HexSum detects which algorithm the checksum uses from its length and immediately reports <strong>MATCH</strong> or <strong>MISMATCH</strong> \u2014 no manual string comparison, no squinting at 64-character strings.</p>\n\n    <h3 class=\"mt-8 text-xl font-bold text-[#451A03]\">Identifying an unknown hash by its length</h3>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\">Hashes frequently appear without labels \u2014 in a database column, a log file, a bug report, or a CTF challenge. Because each algorithm has a fixed output size, the length of the hexadecimal string is a reliable first clue. Count the characters: <strong>32 means MD5</strong> (128 bits), <strong>40 means SHA-1</strong> (160 bits), <strong>64 means SHA-256</strong> (256 bits), <strong>96 means SHA-384</strong> (384 bits), and <strong>128 means SHA-512</strong> (512 bits).</p>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\">There are caveats worth knowing. A 32-character hash could also be NTLM (the Windows password hash, which is MD4-based) or another 128-bit construction \u2014 length narrows the field but does not prove the algorithm. Salted or iterated password hashes look different again: strings beginning with <strong>$2y$</strong> or <strong>$2b$</strong> are bcrypt, <strong>$6$</strong> indicates SHA-512-crypt, and <strong>$y$</strong> marks yescrypt. HexSum's identifier handles the five common unsalted digests and tells you the bit length and security status of each, which covers the vast majority of checksums you will meet in the wild.</p>\n\n    <h3 class=\"mt-8 text-xl font-bold text-[#451A03]\">Hashing text vs. hashing files</h3>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\">Hashing text is straightforward, but one subtlety trips people up: <strong>encoding</strong>. A hash is computed over bytes, not characters, so the same text hashed as UTF-8 versus UTF-16 produces different digests. HexSum always encodes text as UTF-8 \u2014 the web's universal standard \u2014 so its results match the <code>echo -n \"text\" | sha256sum</code> output on Linux and macOS. Watch out for trailing newlines: many command-line tools add one, which changes the hash, so HexSum hashes exactly the characters you provide, nothing more.</p>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\">Hashing files introduces a performance question. Loading a multi-gigabyte file into memory at once can freeze a browser tab, so HexSum reads files in <strong>4&nbsp;MB chunks</strong>, feeding each chunk into the hash state incrementally and showing a progress bar. MD5 and SHA-1 use built-in pure-JavaScript implementations (browsers' Web Crypto API does not provide them), while SHA-256, SHA-384 and SHA-512 use the browser's native, hardware-accelerated cryptography. Everything happens locally \u2014 your files are never uploaded anywhere, which is also why the tool keeps working if you go offline after the page loads.</p>\n\n    <h3 class=\"mt-8 text-xl font-bold text-[#451A03]\">Where hashes shine \u2014 and where they don't</h3>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\">Beyond download verification, hashes quietly power modern computing. <strong>Data deduplication</strong> systems hash file chunks to spot identical data without comparing entire files. <strong>Content-addressed storage</strong> \u2014 used by Git, Docker image layers and IPFS \u2014 names objects by their hash, so identical content is stored once and any corruption is instantly detectable. <strong>Digital signatures</strong> hash a document first and sign the short digest rather than the whole file. <strong>Commitment schemes</strong> let someone prove they knew a value at a certain time by publishing its hash, revealing the value later. And <strong>blockchains</strong> chain blocks together with hashes so that altering history would require recomputing everything after it.</p>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\">The most important \"don't\" concerns <strong>password storage</strong>. A plain SHA-256 hash of a password is dangerously inadequate: it is unsalted, so every user with the password \"letmein123\" shares the identical hash, and it is blindingly fast \u2014 a single GPU can try billions of candidates per second, and precomputed rainbow tables crack common passwords instantly. Proper password storage requires a dedicated <strong>password-hashing function</strong> \u2014 bcrypt, scrypt or Argon2id \u2014 which is intentionally slow, automatically salted, and memory-hard to defeat parallel hardware. If you are building a login system, reach for one of those, never for a raw hash function. HexSum's security panel exists precisely to make this distinction impossible to miss.</p>\n\n    <h3 class=\"mt-8 text-xl font-bold text-[#451A03]\">Practical tips for working with hashes</h3>\n    <p class=\"mt-3 text-stone-700 leading-relaxed\">A few habits will save you headaches. <strong>Compare hashes programmatically or with a verifier</strong> rather than by eye \u2014 humans are terrible at spotting a single changed character in a 64-character string, which is why HexSum's verdict box exists. <strong>Normalize before comparing</strong>: strip whitespace and line breaks, and treat uppercase and lowercase hex as equivalent (HexSum does both automatically). <strong>Prefer SHA-256 for new checksums</strong> you publish; it is universally supported and trusted. <strong>Keep MD5 only for non-security fingerprints</strong> such as ETags, cache keys and duplicate detection. And remember that a hash verifies <em>integrity</em>, not <em>authenticity</em>: a matching checksum proves the file wasn't altered in transit, but only a digital signature \u2014 or fetching the checksum over a trusted channel \u2014 proves it came from who you think it did. For authenticity guarantees, keyed constructions like <strong>HMAC</strong> (a hash combined with a secret key) are the right tool, and they underpin webhook signature verification at companies like Stripe and GitHub.</p>\n    <p class=\"mt-4 text-stone-700 leading-relaxed\">Whether you are verifying an ISO before installing it, fingerprinting data for deduplication, debugging a hash that appears in a log, or simply curious what your name looks like as SHA-512, HexSum gives you all five industry-standard digests in one click \u2014 free, unlimited, and entirely private.</p>\n\n    <h3 class=\"mt-10 text-xl font-bold text-[#451A03]\">Frequently Asked Questions</h3>\n    <div class=\"mt-4 space-y-3\">\n      <details class=\"faq-item rounded-xl ring-1 ring-stone-200 bg-stone-50 open:bg-white transition\">\n        <summary class=\"cursor-pointer px-5 py-4 font-semibold text-[#451A03] list-none flex justify-between items-center\">Is HexSum free, and do I need to sign up? <span class=\"text-amber-600 font-bold\">+</span></summary>\n        <p class=\"px-5 pb-4 text-sm text-stone-600\">Yes. HexSum is completely free with unlimited usage. There is no signup, no account, no paywall and no watermark. Everything runs in your browser, so there is nothing to pay for and nothing to register.</p>\n      </details>\n      <details class=\"faq-item rounded-xl ring-1 ring-stone-200 bg-stone-50 open:bg-white transition\">\n        <summary class=\"cursor-pointer px-5 py-4 font-semibold text-[#451A03] list-none flex justify-between items-center\">Are my files or text uploaded to a server when I hash them? <span class=\"text-amber-600 font-bold\">+</span></summary>\n        <p class=\"px-5 pb-4 text-sm text-stone-600\">No. HexSum computes every hash locally in your browser using the Web Crypto API and built-in JavaScript. Your text and files never leave your device. You can even disconnect from the internet after the page loads and hashing will keep working.</p>\n      </details>\n      <details class=\"faq-item rounded-xl ring-1 ring-stone-200 bg-stone-50 open:bg-white transition\">\n        <summary class=\"cursor-pointer px-5 py-4 font-semibold text-[#451A03] list-none flex justify-between items-center\">How do I verify a downloaded file's checksum with HexSum? <span class=\"text-amber-600 font-bold\">+</span></summary>\n        <p class=\"px-5 pb-4 text-sm text-stone-600\">Drop the downloaded file into HexSum, wait for the five hashes to appear, then paste the checksum published by the software vendor into the verdict box. HexSum auto-detects the algorithm from the hash length and shows a MATCH or MISMATCH verdict. A match means the file arrived intact; a mismatch means it is corrupt or has been tampered with.</p>\n      </details>\n      <details class=\"faq-item rounded-xl ring-1 ring-stone-200 bg-stone-50 open:bg-white transition\">\n        <summary class=\"cursor-pointer px-5 py-4 font-semibold text-[#451A03] list-none flex justify-between items-center\">Which hash algorithm should I use: MD5, SHA-1, SHA-256, SHA-384 or SHA-512? <span class=\"text-amber-600 font-bold\">+</span></summary>\n        <p class=\"px-5 pb-4 text-sm text-stone-600\">For anything security-related, use SHA-256 or SHA-512. MD5 and SHA-1 are broken for security purposes and should only be used for non-security checksums such as detecting accidental corruption or identifying duplicate files. SHA-256 is the modern default; SHA-512 offers the largest security margin and is often faster on 64-bit hardware.</p>\n      </details>\n      <details class=\"faq-item rounded-xl ring-1 ring-stone-200 bg-stone-50 open:bg-white transition\">\n        <summary class=\"cursor-pointer px-5 py-4 font-semibold text-[#451A03] list-none flex justify-between items-center\">Can I use a plain SHA-256 hash to store passwords? <span class=\"text-amber-600 font-bold\">+</span></summary>\n        <p class=\"px-5 pb-4 text-sm text-stone-600\">No. Plain SHA-256 is far too fast to be a safe password hash and offers no salt, so identical passwords produce identical hashes that are trivially crackable with GPUs and rainbow tables. Use a dedicated password-hashing function such as bcrypt, scrypt or Argon2id, which are intentionally slow and include automatic salting.</p>\n      </details>\n      <details class=\"faq-item rounded-xl ring-1 ring-stone-200 bg-stone-50 open:bg-white transition\">\n        <summary class=\"cursor-pointer px-5 py-4 font-semibold text-[#451A03] list-none flex justify-between items-center\">How does HexSum identify an unknown hash algorithm? <span class=\"text-amber-600 font-bold\">+</span></summary>\n        <p class=\"px-5 pb-4 text-sm text-stone-600\">HexSum looks at the length of the hexadecimal string. A 32-character hash is MD5, 40 is SHA-1, 64 is SHA-256, 96 is SHA-384 and 128 is SHA-512. Paste any hash into the Identify tab and HexSum reports the most likely algorithm, its bit length and a security note.</p>\n      </details>\n    </div>\n  </div>\n</article>\n<!--ARTICLE-END-->\n\n<!-- ============ FOOTER ============ -->\n<footer class=\"bg-[#451A03] text-stone-300\">\n  <div class=\"mx-auto max-w-6xl px-4 sm:px-6 py-8 flex flex-col sm:flex-row items-center justify-between gap-4\">\n    <div class=\"flex items-center gap-2\">\n      <span class=\"inline-flex h-8 w-8 items-center justify-center rounded-lg bg-amber-400 text-[#451A03] font-black\">#</span>\n      <span class=\"text-xl font-extrabold text-amber-400\">HexSum</span>\n      <span class=\"text-xs text-stone-400\">\u2014 free hash generator &amp; checksum verifier</span>\n    </div>\n    <nav class=\"flex items-center gap-5 text-sm\">\n      <a href=\"#top\" class=\"hover:text-amber-400 transition\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"hover:text-amber-400 transition\">More Tools</a>\n    </nav>\n  </div>\n  <p class=\"text-center text-[11px] text-stone-500 pb-6 px-4\">All hashing happens locally in your browser. Nothing is uploaded, stored, or tracked.</p>\n<p class=\"fx-credit\" style=\"text-align:center;font-size:12.5px;opacity:.62;margin:10px auto 2px;letter-spacing:.01em\">Made by <a href=\"https://fixoraa.tech\" target=\"_blank\" rel=\"noopener\" style=\"color:inherit;font-weight:700;text-decoration:underline;text-underline-offset:2px\">Fixoraa</a></p>\n</footer>\n\n<script>\n(function () {\n  'use strict';\n  var L = window.HexSumLib;\n  var state = { mode: 'text', hashes: null, upper: false, fileName: '', fileSize: 0 };\n\n  var ALGOS = [\n    { key: 'md5',    name: 'MD5',     bits: 128, hexLen: 32,  webcrypto: null,      badge: 'Legacy \u2014 broken',  badgeCls: 'bg-red-100 text-red-700 ring-red-200' },\n    { key: 'sha1',   name: 'SHA-1',   bits: 160, hexLen: 40,  webcrypto: null,      badge: 'Legacy \u2014 weak',    badgeCls: 'bg-orange-100 text-orange-700 ring-orange-200' },\n    { key: 'sha256', name: 'SHA-256', bits: 256, hexLen: 64,  webcrypto: 'SHA-256', badge: 'Secure \u2014 default', badgeCls: 'bg-green-100 text-green-700 ring-green-200' },\n    { key: 'sha384', name: 'SHA-384', bits: 384, hexLen: 96,  webcrypto: 'SHA-384', badge: 'Secure',           badgeCls: 'bg-green-100 text-green-700 ring-green-200' },\n    { key: 'sha512', name: 'SHA-512', bits: 512, hexLen: 128, webcrypto: 'SHA-512', badge: 'Secure \u2014 strongest', badgeCls: 'bg-green-100 text-green-700 ring-green-200' }\n  ];\n\n  function fmtBytes(n) {\n    if (n < 1024) return n + ' B';\n    var u = ['KB', 'MB', 'GB', 'TB'], i = -1;\n    do { n /= 1024; i++; } while (n >= 1024 && i < u.length - 1);\n    return n.toFixed(2) + ' ' + u[i];\n  }\n\n  function fmtHash(h) { return state.upper ? h.toUpperCase() : h.toLowerCase(); }\n\n  function renderCards() {\n    var wrap = document.getElementById('algo-cards');\n    var html = '';\n    ALGOS.forEach(function (a) {\n      var val = state.hashes ? fmtHash(state.hashes[a.key]) : '\u2014';\n      var placeholder = state.hashes ? '' : ' text-stone-300';\n      html += '<div class=\"rounded-xl bg-white ring-1 ring-stone-200 shadow-sm overflow-hidden\">' +\n        '<div class=\"flex items-center justify-between px-4 sm:px-5 py-2.5 bg-stone-50 border-b border-stone-200\">' +\n          '<div class=\"flex items-center gap-2\">' +\n            '<span class=\"font-bold text-[#451A03]\">' + a.name + '</span>' +\n            '<span class=\"text-[11px] text-stone-500\">' + a.bits + '-bit &middot; ' + a.hexLen + ' hex chars</span>' +\n          '</div>' +\n          '<span class=\"text-[10px] font-bold uppercase tracking-wide rounded-full px-2.5 py-1 ring-1 ' + a.badgeCls + '\">' + a.badge + '</span>' +\n        '</div>' +\n        '<div class=\"flex items-start gap-2 px-4 sm:px-5 py-3\">' +\n          '<code id=\"hash-' + a.key + '\" class=\"hash-mono flex-1 text-[12px] sm:text-[13px] leading-relaxed text-stone-800' + placeholder + '\">' + val + '</code>' +\n          '<button onclick=\"copyHash(\\'' + a.key + '\\', this)\" ' + (state.hashes ? '' : 'disabled') +\n            ' class=\"shrink-0 rounded-md bg-stone-100 hover:bg-amber-100 border border-stone-200 hover:border-amber-400 text-stone-600 hover:text-[#451A03] text-xs font-semibold px-2.5 py-1.5 transition disabled:opacity-40 disabled:cursor-not-allowed\">Copy</button>' +\n        '</div></div>';\n    });\n    wrap.innerHTML = html;\n    document.getElementById('no-input-hint').style.display = state.hashes ? 'none' : 'block';\n    // re-run verdict if an expected hash was pasted\n    var exp = document.getElementById('expected-input').value.trim();\n    if (exp && state.hashes) verifyNow();\n  }\n\n  function copyText(t, btn) {\n    function done() {\n      if (!btn) return;\n      var old = btn.textContent;\n      btn.textContent = 'Copied!';\n      btn.classList.add('copy-flash');\n      setTimeout(function () { btn.textContent = old; btn.classList.remove('copy-flash'); }, 1200);\n    }\n    if (navigator.clipboard && navigator.clipboard.writeText) {\n      navigator.clipboard.writeText(t).then(done, function () { fallback(); });\n    } else fallback();\n    function fallback() {\n      var ta = document.createElement('textarea');\n      ta.value = t; ta.style.position = 'fixed'; ta.style.opacity = '0';\n      document.body.appendChild(ta); ta.select();\n      try { document.execCommand('copy'); } catch (e) {}\n      document.body.removeChild(ta); done();\n    }\n  }\n\n  window.copyHash = function (key, btn) {\n    if (!state.hashes) return;\n    copyText(fmtHash(state.hashes[key]), btn);\n  };\n\n  window.copyAll = function () {\n    if (!state.hashes) return;\n    var o = { tool: 'HexSum' };\n    if (state.fileName) { o.file = state.fileName; o.size_bytes = state.fileSize; }\n    ALGOS.forEach(function (a) { o[a.key] = fmtHash(state.hashes[a.key]); });\n    copyText(JSON.stringify(o, null, 2), document.querySelector('button[onclick=\"copyAll()\"]'));\n  };\n\n  window.toggleCase = function () {\n    state.upper = !state.upper;\n    document.getElementById('case-btn').textContent = state.upper ? 'lowercase' : 'UPPERCASE';\n    try { localStorage.setItem('hexsum-case', state.upper ? 'upper' : 'lower'); } catch (e) {}\n    renderCards();\n  };\n\n  async function sha2hex(bytes, name) {\n    var copy = bytes.slice ? bytes.slice() : new Uint8Array(bytes);\n    var buf = await crypto.subtle.digest(name, copy);\n    return L.bytesToHex(new Uint8Array(buf));\n  }\n\n  async function hashBytes(bytes) {\n    var subtleOK = !!(window.crypto && crypto.subtle);\n    var out = { md5: L.md5Hex(bytes), sha1: L.sha1Hex(bytes) };\n    if (subtleOK) {\n      var r = await Promise.all([\n        sha2hex(bytes, 'SHA-256'), sha2hex(bytes, 'SHA-384'), sha2hex(bytes, 'SHA-512')\n      ]);\n      out.sha256 = r[0]; out.sha384 = r[1]; out.sha512 = r[2];\n    } else {\n      out.sha256 = out.sha384 = out.sha512 = 'unavailable \u2014 SHA-2 needs a secure context (HTTPS or localhost)';\n    }\n    return out;\n  }\n\n  var debounce = null;\n  window.hashTextNow = async function () {\n    var text = document.getElementById('text-input').value;\n    document.getElementById('char-count').textContent = text.length;\n    var bytes = L.stringToBytes(text);\n    document.getElementById('byte-count').textContent = bytes.length;\n    if (text.length === 0) { state.hashes = null; state.fileName = ''; renderCards(); return; }\n    state.hashes = await hashBytes(bytes);\n    state.fileName = ''; state.fileSize = 0;\n    renderCards();\n  };\n\n  document.getElementById('text-input').addEventListener('input', function () {\n    clearTimeout(debounce);\n    debounce = setTimeout(window.hashTextNow, 300);\n  });\n\n  window.clearText = function () {\n    document.getElementById('text-input').value = '';\n    window.hashTextNow();\n  };\n\n  /* ---------- file mode ---------- */\n  var dropZone = document.getElementById('drop-zone');\n  var fileInput = document.getElementById('file-input');\n  dropZone.addEventListener('click', function () { fileInput.click(); });\n  fileInput.addEventListener('change', function () { if (fileInput.files[0]) hashFile(fileInput.files[0]); });\n  ['dragover', 'dragenter'].forEach(function (ev) {\n    dropZone.addEventListener(ev, function (e) { e.preventDefault(); dropZone.classList.add('border-amber-400'); });\n  });\n  ['dragleave', 'drop'].forEach(function (ev) {\n    dropZone.addEventListener(ev, function (e) { e.preventDefault(); dropZone.classList.remove('border-amber-400'); });\n  });\n  dropZone.addEventListener('drop', function (e) {\n    var f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0];\n    if (f) hashFile(f);\n  });\n\n  async function hashFile(file) {\n    var CHUNK = 4 * 1024 * 1024;\n    var md5 = new L.MD5Hasher(), sha1 = new L.SHA1Hasher();\n    var parts = [];\n    var offset = 0;\n    var pw = document.getElementById('progress-wrap');\n    var pb = document.getElementById('progress-bar');\n    var pl = document.getElementById('progress-label');\n    pw.classList.remove('hidden');\n    try {\n      while (offset < file.size) {\n        var slice = file.slice(offset, offset + CHUNK);\n        var buf = new Uint8Array(await slice.arrayBuffer());\n        if (buf.length === 0) break;\n        md5.update(buf); sha1.update(buf);\n        parts.push(buf);\n        offset += buf.length;\n        var pct = file.size ? Math.round((offset / file.size) * 100) : 100;\n        pb.style.width = pct + '%';\n        pl.textContent = 'Reading file\u2026 ' + pct + '% (' + fmtBytes(offset) + ' / ' + fmtBytes(file.size) + ')';\n        await new Promise(function (r) { setTimeout(r, 0); });\n      }\n      pl.textContent = 'Finalizing digests\u2026';\n      var total = new Uint8Array(file.size);\n      var p = 0;\n      for (var i = 0; i < parts.length; i++) { total.set(parts[i], p); p += parts[i].length; }\n      var out = { md5: md5.digest(), sha1: sha1.digest() };\n      if (window.crypto && crypto.subtle) {\n        var r2 = await Promise.all([\n          sha2hex(total, 'SHA-256'), sha2hex(total, 'SHA-384'), sha2hex(total, 'SHA-512')\n        ]);\n        out.sha256 = r2[0]; out.sha384 = r2[1]; out.sha512 = r2[2];\n      } else {\n        out.sha256 = out.sha384 = out.sha512 = 'unavailable \u2014 SHA-2 needs a secure context (HTTPS or localhost)';\n      }\n      state.hashes = out;\n      state.fileName = file.name; state.fileSize = file.size;\n      var fm = document.getElementById('file-meta');\n      fm.classList.remove('hidden');\n      fm.innerHTML = 'Hashed: <span class=\"text-stone-200 font-semibold\">' + escapeHtml(file.name) + '</span> &middot; ' + fmtBytes(file.size);\n      renderCards();\n      pl.textContent = 'Done \u2014 ' + fmtBytes(file.size) + ' hashed in chunks.';\n      pb.style.width = '100%';\n    } catch (err) {\n      pl.textContent = 'Error reading file: ' + (err && err.message ? err.message : err);\n    }\n  }\n\n  function escapeHtml(s) {\n    return String(s).replace(/[&<>\"']/g, function (c) {\n      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c];\n    });\n  }\n\n  /* ---------- verdict ---------- */\n  window.verifyNow = function () {\n    var box = document.getElementById('verdict-box');\n    var exp = document.getElementById('expected-input').value;\n    box.classList.remove('hidden');\n    if (!state.hashes) {\n      box.className = 'mt-3 rounded-xl p-4 text-sm bg-stone-100 text-stone-600 ring-1 ring-stone-200';\n      box.innerHTML = '<strong>Nothing to compare yet.</strong> Hash some text or a file first, then paste the expected checksum.';\n      return;\n    }\n    var norm = L.normalizeHash(exp);\n    if (!norm) {\n      box.className = 'mt-3 rounded-xl p-4 text-sm bg-stone-100 text-stone-600 ring-1 ring-stone-200';\n      box.innerHTML = 'Paste an expected hash above, then press Verify.';\n      return;\n    }\n    if (!L.isHexString(norm)) {\n      box.className = 'mt-3 rounded-xl p-4 text-sm bg-amber-50 text-amber-800 ring-1 ring-amber-200';\n      box.innerHTML = '<strong class=\"font-bold\">\u26a0 Not a valid hash.</strong> Expected value contains non-hexadecimal characters. Hashes use only 0\u20139 and a\u2013f.';\n      return;\n    }\n    var detected = L.detectAlgorithm(norm);\n    var matchedAlgo = null, match = false;\n    if (detected) {\n      var key = { 'MD5': 'md5', 'SHA-1': 'sha1', 'SHA-256': 'sha256', 'SHA-384': 'sha384', 'SHA-512': 'sha512' }[detected.algorithm];\n      var cmp = L.compareHashes(state.hashes[key], norm);\n      match = cmp.match; matchedAlgo = detected.algorithm;\n    } else {\n      // unknown length \u2014 compare against all five\n      var keys = ['md5', 'sha1', 'sha256', 'sha384', 'sha512'];\n      for (var i = 0; i < keys.length; i++) {\n        if (L.compareHashes(state.hashes[keys[i]], norm).match) {\n          match = true;\n          matchedAlgo = ALGOS[i].name + ' (by value match)';\n          break;\n        }\n      }\n    }\n    if (match) {\n      box.className = 'mt-3 rounded-xl p-4 text-sm bg-green-50 text-green-900 ring-1 ring-green-300';\n      box.innerHTML = '<p class=\"text-lg font-extrabold text-green-700\">\u2713 MATCH</p>' +\n        '<p class=\"mt-1\">The expected hash is identical to the computed <strong>' + escapeHtml(matchedAlgo) + '</strong> digest. Integrity confirmed.</p>' +\n        '<p class=\"mt-2 hash-mono text-xs text-green-800 break-all\">' + escapeHtml(norm) + '</p>';\n    } else {\n      box.className = 'mt-3 rounded-xl p-4 text-sm bg-red-50 text-red-900 ring-1 ring-red-300';\n      box.innerHTML = '<p class=\"text-lg font-extrabold text-red-700\">\u2717 MISMATCH</p>' +\n        '<p class=\"mt-1\">The expected hash does <strong>not</strong> match the computed digest' +\n        (detected ? ' for <strong>' + escapeHtml(detected.algorithm) + '</strong> (auto-detected from ' + detected.hexLength + ' hex characters)' : ' for any of the five algorithms') +\n        '. The data was altered or corrupted \u2014 do not trust it.</p>';\n    }\n  };\n  document.getElementById('expected-input').addEventListener('input', function () {\n    var v = document.getElementById('expected-input').value.trim();\n    if (v) window.verifyNow();\n    else document.getElementById('verdict-box').classList.add('hidden');\n  });\n\n  /* ---------- identify mode ---------- */\n  document.getElementById('identify-input').addEventListener('input', function () {\n    var box = document.getElementById('identify-result');\n    var raw = document.getElementById('identify-input').value;\n    var norm = L.normalizeHash(raw);\n    if (!norm) { box.innerHTML = ''; return; }\n    if (!L.isHexString(norm)) {\n      box.innerHTML = '<div class=\"rounded-xl bg-amber-400/10 ring-1 ring-amber-400/40 p-4 text-sm text-amber-200\"><strong>\u26a0 Not hexadecimal.</strong> A hash digest contains only 0\u20139 and a\u2013f. (' + norm.length + ' chars entered)</div>';\n      return;\n    }\n    var d = L.detectAlgorithm(norm);\n    if (d) {\n      var legacy = (d.algorithm === 'MD5' || d.algorithm === 'SHA-1');\n      box.innerHTML = '<div class=\"rounded-xl bg-black/40 ring-1 ring-amber-400/40 p-4\">' +\n        '<p class=\"text-xs uppercase tracking-wider text-stone-400\">Most likely algorithm</p>' +\n        '<p class=\"mt-1 text-2xl font-extrabold text-amber-300\">' + d.algorithm + '</p>' +\n        '<p class=\"mt-1 text-sm text-stone-300\">' + d.bits + '-bit digest &middot; ' + d.hexLength + ' hex characters</p>' +\n        '<p class=\"mt-2 text-xs ' + (legacy ? 'text-red-300' : 'text-green-300') + '\">' + (legacy ? '\u26a0 ' : '\u2713 ') + escapeHtml(d.note) + '</p></div>';\n    } else {\n      box.innerHTML = '<div class=\"rounded-xl bg-black/40 ring-1 ring-stone-600 p-4 text-sm text-stone-300\"><strong class=\"text-stone-100\">Unknown length.</strong> ' + norm.length + ' hex characters doesn\\'t match MD5 (32), SHA-1 (40), SHA-256 (64), SHA-384 (96) or SHA-512 (128). It may be truncated, salted, or a different construction (e.g. bcrypt, HMAC).</div>';\n    }\n  });\n\n  /* ---------- mode tabs ---------- */\n  window.setMode = function (mode) {\n    state.mode = mode;\n    ['text', 'file', 'identify'].forEach(function (m) {\n      document.getElementById('tab-' + m).className = (m === mode ? 'tab-active' : 'tab-idle') + ' rounded-md px-3 sm:px-4 py-2 transition';\n      document.getElementById('pane-' + m).classList.toggle('hidden', m !== mode);\n    });\n    try { localStorage.setItem('hexsum-mode', mode); } catch (e) {}\n  };\n\n  /* ---------- init ---------- */\n  try {\n    var savedCase = localStorage.getItem('hexsum-case');\n    if (savedCase === 'upper') { state.upper = true; document.getElementById('case-btn').textContent = 'lowercase'; }\n    var savedMode = localStorage.getItem('hexsum-mode');\n    if (savedMode === 'file' || savedMode === 'identify') window.setMode(savedMode);\n  } catch (e) {}\n  renderCards();\n})();\n</script>\n</body>\n</html>\n";
export default {
  async fetch(request) {
    const url = new URL(request.url);
    if (url.pathname !== "/" && url.pathname !== "/index.html") {
      return new Response("Not found", { status: 404 });
    }
    return new Response(HTML, {
      headers: { "content-type": "text/html;charset=UTF-8" }
    });
  }
};